package com.chain.contracts;

import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.Map;
import java.util.HashMap;
import java.nio.ByteBuffer;
import java.security.SecureRandom;

/**
 * Smart contract for cross-chain asset bridge
 * Deployed as a sidecar in Kubernetes pod alongside validator node
 */
public class AssetBridgeContract {

    private final ConcurrentHashMap<String, TransferState> pendingTransfers = new ConcurrentHashMap<>();
    private final ScheduledExecutorService scheduler = Executors.newScheduledThreadPool(4);
    private final AtomicLong nonce = new AtomicLong(0);
    private final SecureRandom secureRandom = new SecureRandom();
    private volatile ValidatorSet currentValidators;

    public static class TransferState {
        volatile byte[] proofData;
        volatile CompletableFuture<byte[]> attestationFuture;
        final String transferId;
        final long amount;
        final String recipient;
        volatile boolean finalized;
        volatile CallbackHandle callbackRef;
        final long epoch;

        TransferState(String transferId, long amount, String recipient, long epoch) {
            this.transferId = transferId;
            this.amount = amount;
            this.recipient = recipient;
            this.finalized = false;
            this.epoch = epoch;
        }
    }

    public static class CallbackHandle {
        private final TransferState stateRef;
        private final long createdAt;
        private final long epoch;
        private final AtomicBoolean invalidated;

        CallbackHandle(TransferState state, long epoch) {
            this.stateRef = state;
            this.createdAt = System.nanoTime();
            this.epoch = epoch;
            this.invalidated = new AtomicBoolean(false);
        }

        public TransferState getStateIfValid() {
            if (invalidated.get()) {
                return null;
            }
            return stateRef;
        }

        public boolean invalidate() {
            return invalidated.compareAndSet(false, true);
        }

        public boolean isValid() {
            return !invalidated.get();
        }

        public long getEpoch() {
            return epoch;
        }
    }

    public static class ValidatorSet {
        private final Map<String, byte[]> validators;
        private final int quorum;

        ValidatorSet(Map<String, byte[]> validators, int quorum) {
            this.validators = new HashMap<>(validators);
            this.quorum = quorum;
        }

        public boolean hasQuorum(int attestations) {
            return attestations >= quorum;
        }
    }

    /**
     * Initiates a cross-chain transfer with async attestation gathering
     */
    public CompletableFuture<String> initiateTransfer(String recipient, long amount, byte[] sourceProof) {
        if (recipient == null) {
            throw new IllegalArgumentException("recipient must not be null");
        }
        if (sourceProof == null) {
            throw new IllegalArgumentException("sourceProof must not be null");
        }
        if (amount <= 0) {
            throw new IllegalArgumentException("amount must be positive");
        }
        String transferId = generateTransferId(recipient, amount);
        long epoch = nonce.get();
        TransferState state = new TransferState(transferId, amount, recipient, epoch);
        state.proofData = sourceProof.clone();

        pendingTransfers.put(transferId, state);

        CallbackHandle handle = new CallbackHandle(state, epoch);
        state.callbackRef = handle;

        // Schedule attestation collection with timeout
        state.attestationFuture = collectAttestationsAsync(handle);

        // Schedule cleanup after timeout - safe: uses epoch to prevent stale access
        ScheduledFuture<?> timeoutTask = scheduler.schedule(() -> {
            timeoutTransfer(transferId, handle);
        }, 30, TimeUnit.SECONDS);

        return state.attestationFuture.thenApply(proof -> {
            timeoutTask.cancel(false);
            finalizeTransfer(transferId, proof, epoch);
            return transferId;
        });
    }

    /**
     * Called when attestation timeout fires.
     * Safe: atomically invalidates the handle, then checks epoch match
     * against current state in the map to prevent operating on recycled state.
     */
    private void timeoutTransfer(String transferId, CallbackHandle handle) {
        // Atomically invalidate - only one thread can succeed
        if (!handle.invalidate()) {
            return;
        }

        // Double-check: verify the current map entry matches our epoch
        TransferState currentState = pendingTransfers.get(transferId);
        if (currentState != null && currentState.epoch == handle.getEpoch() && !currentState.finalized) {
            currentState.finalized = true;
            currentState.attestationFuture.completeExceptionally(
                new TimeoutException("Attestation timeout for " + transferId));
            pendingTransfers.remove(transferId, currentState);
        }
    }

    /**
     * Cancel and retry - safe version:
     * 1. Atomically invalidates old handle (prevents timeout callback from acting)
     * 2. Uses new epoch for new state
     * 3. Uses ConcurrentHashMap.remove(key, value) for safe conditional removal
     */
    public CompletableFuture<String> cancelAndRetry(String transferId, byte[] newProof) {
        if (newProof == null) {
            throw new IllegalArgumentException("newProof must not be null");
        }
        TransferState oldState = pendingTransfers.get(transferId);
        if (oldState != null) {
            // Atomically invalidate the old callback - timeout can no longer act
            if (oldState.callbackRef != null) {
                oldState.callbackRef.invalidate();
            }
            // Conditional remove ensures we only remove if it's still the old state
            pendingTransfers.remove(transferId, oldState);
        }

        // New epoch ensures timeout callbacks from old transfer cannot affect new state
        long newEpoch = nonce.incrementAndGet();
        TransferState newState = new TransferState(transferId, oldState != null ? oldState.amount : 0, oldState != null ? oldState.recipient : "", newEpoch);
        newState.proofData = newProof.clone();

        CallbackHandle newHandle = new CallbackHandle(newState, newEpoch);
        newState.callbackRef = newHandle;
        pendingTransfers.put(transferId, newState);

        newState.attestationFuture = collectAttestationsAsync(newHandle);

        ScheduledFuture<?> timeoutTask = scheduler.schedule(() -> {
            timeoutTransfer(transferId, newHandle);
        }, 30, TimeUnit.SECONDS);

        return newState.attestationFuture.thenApply(proof -> {
            timeoutTask.cancel(false);
            finalizeTransfer(transferId, proof, newEpoch);
            return transferId;
        });
    }

    private CompletableFuture<byte[]> collectAttestationsAsync(CallbackHandle handle) {
        return CompletableFuture.supplyAsync(() -> {
            try {
                Thread.sleep(100); // Simulate network delay
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
            }

            // Atomically check validity
            TransferState state = handle.getStateIfValid();
            if (state == null || state.finalized) {
                throw new CompletionException(new IllegalStateException("Transfer invalidated"));
            }

            return state.proofData;
        });
    }

    private void finalizeTransfer(String transferId, byte[] proof, long expectedEpoch) {
        TransferState state = pendingTransfers.get(transferId);
        if (state != null && state.epoch == expectedEpoch) {
            state.finalized = true;
            // In production: emit event, update ledger state
        }
    }

    private String generateTransferId(String recipient, long amount) {
        // Use a cryptographically secure random component to avoid predictable/collision-prone IDs
        byte[] randomBytes = new byte[16];
        secureRandom.nextBytes(randomBytes);
        StringBuilder sb = new StringBuilder("tx_");
        for (byte b : randomBytes) {
            sb.append(String.format("%02x", b));
        }
        sb.append('_').append(nonce.incrementAndGet());
        return sb.toString();
    }

    /**
     * Health check endpoint for Kubernetes liveness probe
     */
    public boolean isHealthy() {
        return !scheduler.isShutdown() && pendingTransfers.size() < 10000;
    }

    public void shutdown() {
        scheduler.shutdownNow();
        pendingTransfers.clear();
    }
}
